(function() {
  var DICTS = [
    {
      key: "lab",
      title: "Quality Control Bench",
      img: "data:image/jpeg;base64,",
      terms: [{"num": 1, "x": 13.0, "y": 31.3, "en": "Zahn cup", "pt": "Copo de viscosidade", "defEn": "Measures viscosity by timing how long the liquid takes to flow through a hole in the bottom.", "defPt": "Mede a viscosidade cronometrando quanto tempo o líquido leva para escoar por um furo no fundo."}, {"num": 2, "x": 14.6, "y": 51.3, "en": "Drawdown bar", "pt": "Barra de aplicação", "defEn": "Spreads a thin, even layer of paint across a test panel.", "defPt": "Espalha uma camada fina e uniforme de tinta sobre um painel de teste."}, {"num": 3, "x": 15.0, "y": 69.8, "en": "Cross-cut adhesion tester", "pt": "Testador de aderência", "defEn": "Cuts a grid pattern into dried paint to test how well it's bonded to the surface.", "defPt": "Corta um padrão de grade na tinta seca para testar se ela está bem aderida à superfície."}, {"num": 4, "x": 35.2, "y": 71.3, "en": "Test panel", "pt": "Painel de teste", "defEn": "The surface where the grid pattern is cut to check paint adhesion.", "defPt": "Superfície onde o padrão de grade é cortado para checar a aderência da tinta."}, {"num": 5, "x": 31.9, "y": 25.4, "en": "Spectrophotometer", "pt": "Espectrofotômetro", "defEn": "Measures the exact color of a sample, catching shade differences the eye can't see.", "defPt": "Mede a cor exata de uma amostra, captando diferenças de tom que o olho não percebe."}, {"num": 6, "x": 59.2, "y": 31.3, "en": "Sample cans", "pt": "Latas de amostra", "defEn": "Hold the batches of paint being compared or tested.", "defPt": "Guardam os lotes de tinta que estão sendo comparados ou testados."}, {"num": 7, "x": 54.7, "y": 68.4, "en": "pH meter", "pt": "Medidor de pH", "defEn": "Measures how acidic or alkaline the liquid formula is.", "defPt": "Mede o quão ácida ou alcalina está a fórmula líquida."}, {"num": 8, "x": 82.0, "y": 34.2, "en": "Magnetic stirrer", "pt": "Agitador magnético", "defEn": "Mixes a liquid sample using a spinning magnet, keeping the blend uniform.", "defPt": "Mistura uma amostra líquida usando um ímã giratório, mantendo a mistura uniforme."}, {"num": 9, "x": 82.0, "y": 78.1, "en": "Safety goggles", "pt": "Óculos de proteção", "defEn": "Required safety equipment in the lab.", "defPt": "Equipamento de proteção obrigatório no laboratório."}]
    },
    {
      key: "products",
      title: "Product Line",
      img: "data:image/jpeg;base64,",
      terms: [{"num": 1, "x": 12.7, "y": 48.8, "en": "Plastic jug", "pt": "Galão plástico", "defEn": "DisperFlow 60. Dispersant: keeps pigment evenly distributed in the paint, prevents it from clumping.", "defPt": "DisperFlow 60. Dispersante: mantém o pigmento distribuído igualmente na tinta, evita que ele se acumule."}, {"num": 2, "x": 36.1, "y": 54.2, "en": "Paint can", "pt": "Lata de tinta", "defEn": "Adesiv-X 200. Adhesion promoter: helps paint stick to porous surfaces.", "defPt": "Adesiv-X 200. Promotor de aderência: ajuda a tinta a grudar em superfícies porosas."}, {"num": 3, "x": 51.8, "y": 54.7, "en": "Pump bottle", "pt": "Frasco com bomba", "defEn": "Lumia-UV 40. UV stabilizer: protects the paint from fading under sun exposure.", "defPt": "Lumia-UV 40. Estabilizante UV: protege a tinta de desbotar com exposição ao sol."}, {"num": 4, "x": 68.0, "y": 54.2, "en": "Foil pouch", "pt": "Bolsa de alumínio", "defEn": "CorroBlock 15. Corrosion inhibitor: protects the metal underneath the paint from rust.", "defPt": "CorroBlock 15. Inibidor de corrosão: protege o metal por baixo da tinta contra ferrugem."}, {"num": 5, "x": 86.6, "y": 64.5, "en": "Steel drum", "pt": "Tambor de aço", "defEn": "FoamZero 8. Anti-foaming agent: prevents air bubbles during mixing and application.", "defPt": "FoamZero 8. Antiespumante: evita bolhas de ar durante a mistura e a aplicação."}]
    }
  ];
  var currentDict = 0;

  var css = `
.pd-fab{position:fixed;top:68px;right:20px;z-index:700;display:flex;align-items:center;gap:9px;
  background:#0d1a30;border:1px solid rgba(255,255,255,.12);border-radius:40px;padding:9px 16px 9px 9px;
  cursor:pointer;box-shadow:0 14px 36px rgba(0,0,0,.4);transition:transform .15s;font-family:Inter,sans-serif}
.pd-fab:hover{transform:translateY(-2px)}
.pd-fab-icon{width:28px;height:28px;border-radius:50%;background:rgba(30,95,174,.25);flex-shrink:0;
  display:flex;align-items:center;justify-content:center}
.pd-fab-icon svg{width:13px;height:13px;stroke:#8FC1FF;fill:none;stroke-width:1.8}
.pd-fab-text{color:#fff;font-size:10.5px;font-weight:800;white-space:nowrap}
@media(max-width:900px){.pd-fab-text{display:none}.pd-fab{padding:9px}}

.pd-overlay{display:none;position:fixed;inset:0;background:rgba(4,9,18,.82);z-index:950;
  align-items:center;justify-content:center;padding:24px;font-family:Inter,sans-serif}
.pd-overlay.open{display:flex}
.pd-modal{width:min(1000px,100%);max-height:90vh;background:#0b1220;border-radius:18px;overflow:hidden;
  display:flex;flex-direction:column;box-shadow:0 30px 80px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.08);
  opacity:0;transform:translateY(-36px)}
.pd-overlay.open .pd-modal{animation:pdSlideDown .38s cubic-bezier(.16,1,.3,1) forwards}
@keyframes pdSlideDown{to{opacity:1;transform:translateY(0)}}
.pd-hd{display:flex;align-items:center;justify-content:space-between;padding:14px 22px 0}
.pd-hd-title{font-size:14px;font-weight:800;color:#fff}
.pd-hd-sub{font-size:11px;color:rgba(255,255,255,.5);margin-top:2px}
.pd-close{background:none;border:none;color:rgba(255,255,255,.5);cursor:pointer;padding:4px}
.pd-close svg{width:20px;height:20px;stroke:currentColor;fill:none;stroke-width:2}
.pd-close:hover{color:#fff}
.pd-tabs{display:flex;gap:6px;padding:14px 22px 0}
.pd-tab{font-family:Inter,sans-serif;background:none;border:none;cursor:pointer;padding:9px 14px;
  font-size:11px;font-weight:800;letter-spacing:.03em;color:rgba(255,255,255,.4);
  border-bottom:2px solid transparent}
.pd-tab.active{color:#8FC1FF;border-bottom-color:#8FC1FF}
.pd-body{display:flex;flex:1;overflow-y:auto;min-height:0;padding-top:14px}
@media(max-width:760px){.pd-body{flex-direction:column}}
.pd-photo-col{flex:1.3;padding:20px;min-width:0}
.pd-photo-wrap{position:relative;border-radius:12px;overflow:hidden}
.pd-photo-wrap img{width:100%;display:block}
.pd-marker{position:absolute;transform:translate(-50%,-50%);width:26px;height:26px;border-radius:50%;
  background:#1E5FAE;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center;
  cursor:pointer;border:2px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.5);transition:transform .15s}
.pd-marker:hover,.pd-marker.active{transform:translate(-50%,-50%) scale(1.18);background:#E8621A}
.pd-vocab-col{flex:1;padding:20px;border-left:1px solid rgba(255,255,255,.08);min-width:0}
.pd-vocab-hint{font-size:11px;color:rgba(255,255,255,.45);margin-bottom:14px}
.pd-entry{display:flex;gap:10px;padding:10px 8px;border-radius:10px;cursor:pointer;transition:background .15s}
.pd-entry:hover,.pd-entry.active{background:rgba(30,95,174,.15)}
.pd-entry-num{flex-shrink:0;width:22px;height:22px;border-radius:50%;background:rgba(255,255,255,.1);
  color:rgba(255,255,255,.6);font-size:10.5px;font-weight:800;display:flex;align-items:center;justify-content:center}
.pd-entry.active .pd-entry-num{background:#E8621A;color:#fff}
.pd-entry-en{font-size:13px;font-weight:800;color:#fff}
.pd-entry-pt{font-size:11px;color:#8FC1FF;font-weight:600;margin:1px 0 3px}
.pd-entry-def{font-size:11.5px;line-height:1.5;color:rgba(255,255,255,.75)}
.pd-entry-def-pt{font-size:11px;line-height:1.5;color:rgba(255,255,255,.4);font-style:italic;margin-top:2px}
`;
  var style = document.createElement("style");
  style.textContent = css;
  document.head.appendChild(style);

  function renderDict(idx) {
    currentDict = idx;
    var d = DICTS[idx];
    var tabsHtml = DICTS.map(function(dd, i) {
      return '<button class="pd-tab' + (i === idx ? ' active' : '') + '" onclick="PictureDict.switchTo(' + i + ')">' + dd.title + '</button>';
    }).join("");
    var markersHtml = d.terms.map(function(t) {
      return '<div class="pd-marker" data-num="' + t.num + '" style="left:' + t.x + '%;top:' + t.y + '%" onclick="PictureDict.select(' + t.num + ')">' + t.num + '</div>';
    }).join("");
    var entriesHtml = d.terms.map(function(t) {
      return '<div class="pd-entry" data-num="' + t.num + '" onclick="PictureDict.select(' + t.num + ')">' +
        '<div class="pd-entry-num">' + t.num + '</div>' +
        '<div><div class="pd-entry-en">' + t.en + '</div><div class="pd-entry-pt">' + t.pt + '</div><div class="pd-entry-def">' + t.defEn + '</div><div class="pd-entry-def-pt">' + t.defPt + '</div></div>' +
        '</div>';
    }).join("");

    document.getElementById("pd-tabs").innerHTML = tabsHtml;
    document.getElementById("pd-photo-wrap").innerHTML = '<img src="' + d.img + '" alt="' + d.title + '">' + markersHtml;
    document.getElementById("pd-entries").innerHTML = entriesHtml;
    document.getElementById("pd-vocab-hint").textContent = d.terms.length + " terms from " + d.title.toLowerCase();
  }

  var html = `
<div class="pd-overlay" id="pd-overlay" onclick="if(event.target===this)PictureDict.close()">
  <div class="pd-modal">
    <div class="pd-hd">
      <div><div class="pd-hd-title">Picture Dictionary</div><div class="pd-hd-sub">Click a marker or a term to see it in English and Portuguese</div></div>
      <button class="pd-close" onclick="PictureDict.close()"><svg viewBox="0 0 24 24"><path d="M18 6L6 18M6 6l12 12"/></svg></button>
    </div>
    <div class="pd-tabs" id="pd-tabs"></div>
    <div class="pd-body">
      <div class="pd-photo-col">
        <div class="pd-photo-wrap" id="pd-photo-wrap"></div>
      </div>
      <div class="pd-vocab-col">
        <div class="pd-vocab-hint" id="pd-vocab-hint"></div>
        <div id="pd-entries"></div>
      </div>
    </div>
  </div>
</div>
`;

  function inject() {
    var wrap = document.createElement("div");
    wrap.innerHTML = html;
    document.body.appendChild(wrap);
    renderDict(0);

    var hdrRight = document.querySelector(".hdr-right");
    if (hdrRight) {
      var link = document.createElement("a");
      link.className = "hdr-link";
      link.href = "#";
      link.textContent = "Picture Dictionary";
      link.onclick = function(e) { e.preventDefault(); window.PictureDict.open(); };
      hdrRight.appendChild(link);
    } else {
      var fab = document.createElement("div");
      fab.className = "pd-fab";
      fab.onclick = function() { window.PictureDict.open(); };
      fab.innerHTML = '<div class="pd-fab-icon"><svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg></div><div class="pd-fab-text">Picture Dictionary</div>';
      document.body.appendChild(fab);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", inject);
  } else {
    inject();
  }

  window.PictureDict = {
    open: function() { document.getElementById("pd-overlay").classList.add("open"); },
    close: function() { document.getElementById("pd-overlay").classList.remove("open"); },
    switchTo: function(idx) { renderDict(idx); },
    select: function(num) {
      document.querySelectorAll(".pd-marker").forEach(function(m){ m.classList.toggle("active", m.dataset.num == num); });
      document.querySelectorAll(".pd-entry").forEach(function(e){ e.classList.toggle("active", e.dataset.num == num); });
      var entry = document.querySelector('.pd-entry[data-num="' + num + '"]');
      if (entry) entry.scrollIntoView({block: "nearest", behavior: "smooth"});
    }
  };

  document.addEventListener("keydown", function(e) {
    if (e.key === "Escape") window.PictureDict.close();
  });
})();
